    'site_address_help' => 'आपका डाक या कार्यालय का पता जो आपके पाद लेख, हमसे संपर्क करें पृष्ठ और स्थान मानचित्र पर दिखाई देता है। यह पाठ भाषा-विशिष्ट है - इसे प्रत्येक भाषा के लिए अलग से दर्ज करें।',
    'site_map_lat_help' => 'आपके स्थान का अक्षांश, दशमलव डिग्री में (उदाहरण 36.6736)। नीचे दिए गए मानचित्र पर क्लिक करने से स्वचालित रूप से पॉप्युलेट हो जाएगा - आमतौर पर मैन्युअल टाइपिंग की आवश्यकता नहीं होती है।',
    'site_map_lng_help' => 'आपके स्थान का देशांतर, दशमलव डिग्री में (उदाहरण 48.4787)। नीचे दिए गए मानचित्र पर क्लिक करने से स्वचालित रूप से पॉप्युलेट हो जाएगा - आमतौर पर मैन्युअल टाइपिंग की आवश्यकता नहीं होती है।',
    'meta_title_help' => 'वह शीर्षक जो खोज इंजन और ब्राउज़र टैब तब प्रदर्शित करते हैं जब किसी निश्चित पृष्ठ का अपना शीर्षक नहीं होता है। इसे छोटा रखें - लगभग 50 से 60 अक्षर सर्वोत्तम हैं। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'meta_description_help' => 'एक संक्षिप्त सारांश जो खोज इंजन परिणामों में आपकी साइट के शीर्षक के नीचे प्रदर्शित होता है, जब किसी पृष्ठ का अपना विवरण नहीं होता है। लगभग 150 से 160 अक्षर उपयुक्त है। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'og_image_help' => 'वह छवि जो तब प्रदर्शित होगी जब आपकी साइट के पेज सोशल नेटवर्क (फेसबुक, ट्विटर, लिंक्डइन आदि) पर साझा किए जाएंगे। छवि का पूरा पता दर्ज करें, अधिमानतः कम से कम 1200 x 630 पिक्सेल।',
    'google_analytics_id_help' => 'साइट विज़िटर आंकड़ों को ट्रैक करने के लिए आपकी Google Analytics माप आईडी। इसे अपने Google Analytics खाते, एडमिन → डेटा स्ट्रीम अनुभाग में खोजें। प्रारूप: G-XXXXXXXXXX।',
    'google_tag_manager_id_help' => 'कोड संपादित किए बिना ट्रैकिंग स्क्रिप्ट प्रबंधित करने के लिए आपकी Google टैग प्रबंधक कंटेनर आईडी। इसे अपने Google टैग प्रबंधक खाते में ढूंढें. प्रारूप: GTM-XXXXXXX.',
    'google_search_console_help' => 'Google खोज कंसोल में आपकी साइट का स्वामित्व साबित करने के लिए Google जो सत्यापन कोड प्रदान करता है। केवल कोड मान दर्ज करें, संपूर्ण HTML टैग नहीं।',
    'robots_txt_help' => 'निर्देश जो खोज इंजनों को बताते हैं कि वे आपकी साइट के किन पृष्ठों पर जा सकते हैं या नहीं। इसे केवल तभी बदलें जब आप robots.txt नियमों से परिचित हों - यहां एक गलती आपकी पूरी साइट को खोज इंजन से छिपा सकती है।',
    'payment_zarinpal_merchant_help' => 'ज़ारिनपाल के माध्यम से ऑनलाइन कार्ड भुगतान संसाधित करने के लिए आपकी ज़ारिनपाल मर्चेंट आईडी। इसे अपने ज़रीनपाल पैनल में खोजें।',
    'payment_zarinpal_sandbox_help' => 'चालू होने पर, ज़रीनपाल भुगतान परीक्षण मोड में किया जाता है और कोई वास्तविक धन हस्तांतरित नहीं किया जाता है - खरीद प्रक्रिया का परीक्षण करते समय इस मोड का उपयोग करें। ग्राहकों से वास्तविक भुगतान प्राप्त करने से पहले इसे बंद कर दें।',
    'payment_receipt_bank_name_help' => 'जब ग्राहक बैंक जमा विधि का चयन करता है तो ग्राहकों को जिस बैंक में जमा करना चाहिए उसका नाम भुगतान पृष्ठ पर प्रदर्शित होता है। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'payment_receipt_account_number_help' => 'आपका बैंक खाता नंबर उन ग्राहकों को प्रदर्शित किया जाएगा जो बैंक जमा विधि चुनते हैं। नंबर वैसे ही दर्ज करें जैसे वे आपके बैंक स्टेटमेंट पर दिखाई देते हैं।',
    'payment_receipt_iban_help' => 'आपका बैंक खाता नंबर (IBAN) उन ग्राहकों को प्रदर्शित किया जाएगा जो बैंक जमा विधि चुनते हैं। ईरान में, यह संख्या 24 अंकों की होती है और IR से शुरू होती है, जैसे IR000000000000000000000।',
    'payment_receipt_swift_help' => 'आपका स्विफ्ट/बाइक बैंक कोड उन अंतरराष्ट्रीय ग्राहकों को प्रदर्शित किया जाएगा जो बैंक जमा विधि चुनते हैं। यह आमतौर पर 8 या 11 अक्षर लंबा होता है और आपके बैंक द्वारा प्रदान किया जाता है।',
    'payment_receipt_instructions_help' => 'बैंक हस्तांतरण का चयन करने के बाद भुगतान पृष्ठ पर ग्राहकों को अतिरिक्त जानकारी प्रदर्शित होती है, जैसे भुगतान रसीद कैसे भेजें। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'smtp_host_help' => 'आपके ईमेल प्रदाता के एसएमटीपी सर्वर पते का उपयोग ऑर्डर पुष्टिकरण जैसे ईमेल भेजने के लिए किया जाता है। आपके ईमेल प्रदाता या होस्ट, जैसे smtp.gmail.com द्वारा दिया गया।',
    'smtp_port_help' => 'वह पोर्ट नंबर जिसका उपयोग आपका ईमेल सर्वर मेल भेजने के लिए करता है। सामान्य मान 587 (टीएलएस) या 465 (एसएसएल) हैं - यदि अनिश्चित हो तो अपने ईमेल प्रदाता से संपर्क करें।',
    'smtp_username_help' => 'आपके ईमेल सर्वर में लॉग इन करने के लिए उपयोगकर्ता नाम - आमतौर पर आपका पूरा ईमेल पता।',
    'smtp_password_help' => 'उपरोक्त खाता पासवर्ड. जीमेल जैसी सेवाओं के लिए, यह आमतौर पर एक अलग "ऐप पासवर्ड" होता है जिसे आप अपने सामान्य लॉगिन पासवर्ड के बजाय विशेष रूप से इस उद्देश्य के लिए बनाते हैं।',
    'smtp_from_address_help' => 'वह ईमेल पता जो साइट द्वारा ग्राहकों को भेजे जाने वाले ईमेल में प्रेषक के रूप में दिखाई देता है, जैसे कि no-reply@yourcompany.com।',
    'smtp_from_name_help' => 'वह नाम जो साइट द्वारा ग्राहकों को भेजे जाने वाले ईमेल पर प्रेषक के रूप में दिखाई देता है, जैसे आपकी कंपनी का नाम।',
    'sms_provider_help' => 'ग्राहकों को एसएमएस भेजने के लिए एसएमएस सेवा का उपयोग किया जाता है। वह सेवा चुनें जहां आपका खाता है.',
    'sms_api_key_help' => 'आपकी चुनी गई एसएमएस सेवा की एपीआई कुंजी का उपयोग आपकी ओर से एसएमएस भेजने को अधिकृत करने के लिए किया जाता है। इसे अपने सर्वर पैनल में खोजें.',
    'sms_sender_help' => 'आपकी एसएमएस सेवा द्वारा आपको निर्दिष्ट प्रेषक का नंबर या नाम - ग्राहकों द्वारा प्राप्त एसएमएस में प्रेषक के रूप में यही प्रदर्शित किया जाएगा।',
    'sms_otp_template_help' => 'एक एसएमएस टेक्स्ट जो ग्राहकों को एक बार का प्रमाणीकरण कोड भेजता है। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'sms_order_confirmed_template_help' => 'एसएमएस टेक्स्ट जो ऑर्डर की पुष्टि होने पर ग्राहक को भेजा जाता है। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'sms_order_shipped_template_help' => 'एसएमएस टेक्स्ट जो ऑर्डर भेजे जाने पर ग्राहक को भेजा जाता है। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'contact_notify_email_help' => 'वह ईमेल पता जो हमारे संपर्क फ़ॉर्म के माध्यम से भेजे गए प्रत्येक संदेश की एक प्रति प्राप्त करेगा।',
    'contact_notify_sms_help' => 'वह फ़ोन नंबर जो एसएमएस अधिसूचना सक्षम होने पर संपर्क फ़ॉर्म के प्रत्येक नए संदेश के लिए एक एसएमएस प्राप्त करेगा।',
    'contact_recaptcha_site_key_help' => 'संपर्क फ़ॉर्म को स्पैम और बॉट्स से बचाने के लिए आपकी Google reCAPTCHA साइट कुंजी का उपयोग किया जाता है। इसे Google reCAPTCHA व्यवस्थापक पैनल में ढूंढें।',
    'contact_recaptcha_secret_key_help' => 'आपकी Google reCAPTCHA गुप्त कुंजी, फ़ॉर्म सबमिशन की पुष्टि करने के लिए उपरोक्त साइट कुंजी के साथ उपयोग की जाती है। इस कुंजी को गोपनीय रखें.',
    'contact_recaptcha_enabled_help' => 'चालू होने पर, आगंतुकों को संपर्क फ़ॉर्म सबमिट करने से पहले एक रीकैप्चा जांच पास करनी होगी, जो स्पैम को रोकने में मदद करती है। इसे ऊपर साइट कुंजी और गुप्त कुंजी सेट करने की आवश्यकता है।',
    'about_years_help' => 'उदाहरण के लिए, मुख पृष्ठ के हमारे बारे में अनुभाग में प्रदर्शित अनुभव के वर्षों की संख्या 25 है।',
    'about_title_help' => 'मुख्य शीर्षक मुख पृष्ठ के परिचय अनुभाग और "हमारे बारे में" अनुभाग में प्रदर्शित होता है। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'about_desc_help' => 'वह पैराग्राफ जो शीर्षक के अंतर्गत, मुख पृष्ठ के परिचय अनुभाग में और "हमारे बारे में" अनुभाग में दिखाई देता है। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'about_feature_1_help' => 'होम पेज के "हमारे बारे में" अनुभाग में सूचीबद्ध तीन संक्षिप्त हाइलाइट्स में से एक, जैसे कि एक प्रमुख ताकत या उपलब्धि। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'about_feature_2_help' => 'होम पेज के "हमारे बारे में" अनुभाग में सूचीबद्ध तीन संक्षिप्त हाइलाइट्स में से एक, जैसे कि एक प्रमुख ताकत या उपलब्धि। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
    'about_feature_3_help' => 'होम पेज के "हमारे बारे में" अनुभाग में सूचीबद्ध तीन संक्षिप्त हाइलाइट्स में से एक, जैसे कि एक प्रमुख ताकत या उपलब्धि। यह पाठ प्रत्येक भाषा के लिए विशिष्ट है।',
